import React, { useContext } from 'react';
import { Link } from 'gatsby';
import {
  Header as ShellHeader,
  HeaderMenuButton,
  SkipToContent,
} from 'carbon-components-react';
import { Launch20 } from '@carbon/icons-react';
import cx from 'classnames';

import NavContext from 'gatsby-theme-carbon/src/util/context/NavContext';
import * as styles from 'gatsby-theme-carbon/src/components/Header/Header.module.scss';

const DOCS_URL =
  'https://www.ibm.com/docs/en/masv-and-l/cd?topic=applications-maximo-application-framework-configuration-practices';

const CustomHeader = () => {
  const { leftNavIsOpen, toggleNavState } = useContext(NavContext);

  return (
    <ShellHeader aria-label="Header" className={styles.header}>
      <SkipToContent href="#main-content" className={styles.skipToContent} />
      <HeaderMenuButton
        className={cx('bx--header__action--menu', styles.headerButton)}
        aria-label="Open menu"
        onClick={() => {
          toggleNavState('leftNavIsOpen');
          toggleNavState('switcherIsOpen', 'close');
        }}
        isActive={leftNavIsOpen}
      />
      <Link className={styles.headerName} to="/">
        <span>MAF Configuration Practices</span>
      </Link>
      <div className="header-migration-notice">
        <span className="header-migration-tag">DEPRECATED</span>
        <span className="header-migration-text">
          Moved to IBM Documentation
        </span>
        <a
          href={DOCS_URL}
          target="_blank"
          rel="noopener noreferrer"
          className="header-migration-link"
        >
          <span>Go to IBM Docs</span>
          <Launch20 aria-label="Open IBM Docs in new tab" />
        </a>
      </div>
    </ShellHeader>
  );
};

export default CustomHeader;
