import React from 'react';
import { HomepageBanner, HomepageCallout } from 'gatsby-theme-carbon';
import { Launch20 } from '@carbon/icons-react';

// Component to be shadowed
import HomepageTemplate from 'gatsby-theme-carbon/src/templates/Homepage';

import HomepageBannerBackground from '../../images/background.png';

const DOCS_URL =
  'https://www.ibm.com/docs/en/masv-and-l/cd?topic=applications-maximo-application-framework-configuration-practices';

const BannerText = () => (
  <>
    <h1 className="banner-text-blurb">
      MAF Configuration Practices
    </h1>
  </>
);

const FirstCallout = () => (
  <HomepageCallout
    leftText={() => (
      <>
        <strong>Documentation Moved</strong>
      </>
    )}
    rightText={() => (
      <p>
        All topics, configuration practices, and articles have moved to{' '}
        <strong>IBM Documentation</strong>. This repository and portal are no longer updated.
        <br />
        <br />
        <a
          href={DOCS_URL}
          target="_blank"
          rel="noopener noreferrer"
          style={{
            display: 'inline-flex',
            alignItems: 'center',
            gap: '0.5rem',
            color: '#0f62fe',
            fontWeight: 600,
            textDecoration: 'underline',
          }}
        >
          <span>Open MAF Configuration Practices on IBM Documentation</span>
          <Launch20 aria-label="Open IBM Docs in new tab" />
        </a>
      </p>
    )}
  />
);

const customProps = {
  Banner: (
    <HomepageBanner renderText={BannerText} image={HomepageBannerBackground} />
  ),
  FirstCallout: <FirstCallout />,
  SecondCallout: <></>,
};

// spreading the original props gives us props.children (mdx content)
function ShadowedHomepage(props) {
  return <HomepageTemplate {...props} {...customProps} />;
}

export default ShadowedHomepage;
